import React, { useState } from 'react';
import { backendApi } from '../api/backend';

const CACHE_KEY = 'carrent_daily_cars_cache';

export default function ApiLab() {
  // รองรับทั้ง Vite (import.meta.env) และ Create React App (process.env)
  const baseUrl =
    (typeof import.meta !== 'undefined' && import.meta.env?.VITE_API_URL) ||
    process.env.REACT_APP_API_URL ||
    'http://localhost:8080';

  const [searchQuery, setSearchQuery] = useState('Toyota');
  const [status, setStatus] = useState('idle'); // 'idle' | 'loading' | 'success' | 'error'
  const [requestUrl, setRequestUrl] = useState(
    `${baseUrl}/api/cars?search=Toyota`
  );
  const [responseData, setResponseData] = useState('ยังไม่ได้ส่ง request');
  const [cacheNotice, setCacheNotice] = useState('');

  // ฟังก์ชันแปลงข้อมูลให้อยู่ในรูปแบบมาตรฐานของ Car Object (toCar)
  const toCar = (item) => ({
    id: item.id ?? item.ID ?? null,
    name:
      item.name ||
      [item.brand, item.model].filter(Boolean).join(' ') ||
      'ไม่ระบุรุ่นรถ',
    brand: item.brand || '',
    model: item.model || '',
    type: item.type || item.category || 'Sedan',
    pricePerDay: Number(item.price_per_day ?? item.pricePerDay ?? item.price ?? 0),
    imageUrl: item.image_url || item.imageUrl || item.image || '',
    available: item.available ?? true,
  });

  // ฟังก์ชันกลางสำหรับยิง API
  const sendRequest = async (path, transformToCar = false) => {
    const fullUrl = `${baseUrl}${path}`;
    setRequestUrl(fullUrl);
    setStatus('loading');
    setCacheNotice('');
    setResponseData('กำลังส่ง request...');

    const startTime = performance.now();
    try {
      const res = await fetch(fullUrl);
      const elapsed = Math.round(performance.now() - startTime);

      if (!res.ok) {
        throw new Error(`HTTP ${res.status} ${res.statusText}`);
      }

      const rawData = await res.json();
      let output = rawData;

      if (transformToCar) {
        output = Array.isArray(rawData)
          ? rawData.map(toCar)
          : toCar(rawData);
      }

      setStatus('success');
      setCacheNotice(`ตอบกลับสำเร็จใน ${elapsed} ms`);
      setResponseData(JSON.stringify(output, null, 2));
    } catch (err) {
      setStatus('error');
      setResponseData(`Error: ${err.message || 'Failed to fetch'}`);
    }
  };

  // ทดสอบ getCars() ผ่าน Cache รายวันใน localStorage
  const handleGetCarsWithDailyCache = async () => {
    const fullUrl = `${baseUrl}/api/cars`;
    setRequestUrl(fullUrl);
    setStatus('loading');

    const today = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
    const startTime = performance.now();

    try {
      const cachedRaw = localStorage.getItem(CACHE_KEY);
      if (cachedRaw) {
        const parsed = JSON.parse(cachedRaw);
        if (parsed.date === today && Array.isArray(parsed.data)) {
          const elapsed = Math.round(performance.now() - startTime);
          setStatus('success');
          setCacheNotice(`อ่านจาก localStorage cache (${elapsed} ms)`);
          setResponseData(JSON.stringify(parsed.data, null, 2));
          return;
        }
      }

      // ถ้ายังไม่มี cache หรือหมดวันแล้ว ให้ยิงจริง
      const data = await backendApi.getCars();
      const elapsed = Math.round(performance.now() - startTime);
      localStorage.setItem(
        CACHE_KEY,
        JSON.stringify({ date: today, data })
      );

      setStatus('success');
      setCacheNotice(`ยิง API จริงและบันทึกลง cache แล้ว (${elapsed} ms)`);
      setResponseData(JSON.stringify(data, null, 2));
    } catch (err) {
      setStatus('error');
      setResponseData(`Error: ${err.message || 'Failed to fetch'}`);
    }
  };

  // ล้าง cache ใน localStorage
  const handleClearCache = () => {
    localStorage.removeItem(CACHE_KEY);
    setCacheNotice('ล้าง cache เรียบร้อยแล้ว');
  };

  // สีของป้ายสถานะด้านบนกล่องผลลัพธ์
  const statusBadgeStyle = {
    idle: 'bg-slate-200/80 text-slate-600',
    loading: 'bg-amber-100 text-amber-800',
    success: 'bg-emerald-100 text-emerald-700',
    error: 'bg-red-100 text-red-700',
  };

  return (
    <div className="bg-white min-h-[calc(100vh-64px)] py-12 px-6 text-slate-900">
      <div className="max-w-3xl mx-auto space-y-6">
        {/* หัวข้อและคำอธิบาย */}
        <div className="space-y-2">
          <h1 className="text-3xl font-extrabold tracking-tight text-slate-900">
            API Lab
          </h1>
          <p className="text-sm text-gray-600">
            กดปุ่มแล้วดูว่า Go Backend ตอบอะไรกลับมา ก่อนจะเอาไปใช้ในหน้าจริง
          </p>
          <div className="text-xs text-gray-500 pt-1 flex items-center gap-2 flex-wrap">
            <span>Base URL ปัจจุบัน:</span>
            <code className="bg-blue-50 text-[#1d64f2] font-mono px-2.5 py-0.5 rounded-md border border-blue-100">
              {baseUrl}
            </code>
          </div>
        </div>

        {/* แถวปุ่ม Endpoint ด่วน */}
        <div className="flex flex-wrap gap-2.5 pt-1">
          <button
            type="button"
            onClick={() => sendRequest('/api/cars', false)}
            className="bg-blue-50 hover:bg-blue-100 text-[#1d64f2] border border-blue-200/80 font-mono text-xs font-semibold px-3.5 py-1.5 rounded-full transition"
          >
            GET /api/cars
          </button>
          <button
            type="button"
            onClick={() => sendRequest('/api/cars/1', false)}
            className="bg-blue-50 hover:bg-blue-100 text-[#1d64f2] border border-blue-200/80 font-mono text-xs font-semibold px-3.5 py-1.5 rounded-full transition"
          >
            GET /api/cars/1
          </button>
          <button
            type="button"
            onClick={() => sendRequest('/health', false)}
            className="bg-blue-50 hover:bg-blue-100 text-[#1d64f2] border border-blue-200/80 font-mono text-xs font-semibold px-3.5 py-1.5 rounded-full transition"
          >
            GET /health
          </button>
        </div>

        {/* ช่องค้นหา + ปุ่ม ดู JSON ดิบ / ผ่าน toCar แล้ว */}
        <div className="flex flex-col sm:flex-row gap-3">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setRequestUrl(
                `${baseUrl}/api/cars?search=${encodeURIComponent(e.target.value)}`
              );
            }}
            placeholder="พิมพ์คำค้นหา เช่น Toyota..."
            className="flex-1 bg-white border border-gray-200 rounded-xl px-4 py-2.5 text-sm text-slate-800 focus:outline-none focus:border-[#1d64f2]"
          />
          <div className="flex gap-2.5">
            <button
              type="button"
              onClick={() =>
                sendRequest(
                  `/api/cars?search=${encodeURIComponent(searchQuery)}`,
                  false
                )
              }
              className="bg-[#1d64f2] hover:bg-blue-700 text-white font-semibold text-xs px-5 py-2.5 rounded-xl transition shadow-sm"
            >
              ดู JSON ดิบ
            </button>
            <button
              type="button"
              onClick={() =>
                sendRequest(
                  `/api/cars?search=${encodeURIComponent(searchQuery)}`,
                  true
                )
              }
              className="bg-white hover:bg-blue-50 text-[#1d64f2] border border-blue-200 font-semibold text-xs px-5 py-2.5 rounded-xl transition"
            >
              ผ่าน toCar แล้ว
            </button>
          </div>
        </div>

        {/* ปุ่มทดสอบ Cache รายวัน + ล้าง cache */}
        <div className="flex items-center gap-4 flex-wrap">
          <button
            type="button"
            onClick={handleGetCarsWithDailyCache}
            className="bg-white hover:bg-blue-50 text-[#1d64f2] border border-blue-200 font-semibold text-xs px-5 py-2.5 rounded-xl transition shadow-xs"
          >
            getCars() รถทั้งหมด ผ่าน cache รายวัน
          </button>
          <button
            type="button"
            onClick={handleClearCache}
            className="text-xs text-[#1d64f2] underline hover:text-blue-800 font-medium"
          >
            ล้าง cache
          </button>
          {cacheNotice && (
            <span className="text-xs text-emerald-600 font-medium">
              {cacheNotice}
            </span>
          )}
        </div>

        {/* คำอธิบายใต้ปุ่ม + แสดง Method และ URL ที่ยิง */}
        <div className="space-y-1 pt-1">
          <p className="text-xs text-gray-500">
            กดครั้งแรกจะช้า (ยิงจริง) กดซ้ำจะเร็วมาก (อ่านจาก localStorage)
          </p>
          <p className="font-mono text-xs text-gray-500 break-all">
            GET {requestUrl}
          </p>
        </div>

        {/* กล่องแสดงผลลัพธ์ Request / Response */}
        <div className="bg-white border border-gray-200 rounded-2xl overflow-hidden shadow-xs">
          {/* แถบหัวกล่องสีฟ้าอ่อนแสดงสถานะ */}
          <div className="bg-[#eef4ff] border-b border-blue-100 px-5 py-3 flex items-center gap-2.5">
            <span className="text-xs font-semibold text-slate-700">สถานะ</span>
            <span
              className={`font-mono text-[11px] font-semibold px-2.5 py-0.5 rounded-md ${statusBadgeStyle[status]}`}
            >
              {status}
            </span>
          </div>

          {/* เนื้อหา JSON หรือข้อความแจ้งเตือน */}
          <div className="p-5">
            <pre className="font-mono text-xs text-slate-700 whitespace-pre-wrap break-words leading-relaxed max-h-96 overflow-y-auto">
              {responseData}
            </pre>
          </div>
        </div>
      </div>
    </div>
  );
}
